def cantor_numbering(N: int) -> str:
    denominator = 1
    numerator = N + 1
    while numerator > denominator:
        numerator, denominator = numerator % denominator, denominator + numerator // denominator
    if numerator == 0:
        numerator = denominator
    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    """
    :param num_str: A string representing the number string.
    :param N: An integer representing the length of the number string.
    :param K: An integer representing the number of multiplication signs to insert.
    :return: The maximum product that can be obtained by inserting K multiplication signs into the number string.
    """

    # Initialize the maximum product to be 0
    max_product = 0

    # Loop through all possible placements of the K multiplication signs
    for i in range(K + 1):
        for j in range(i + 1, K + 1):
            for k in range(j + 1, K + 1):
                # Calculate the current product
                product = 1
                for l in range(N):
                    if l != i and l != j and l != k:
                        product *= int(num_str[l])
                    elif l == i or l == j or l == k:
                        product *= 10

                # Update the maximum product
                if product > max_product:
                    max_product = product

    # Return the maximum product
    return max_product

