def count_passing_ways(n: int, m: int) -> int:
    # Build a cache dictionary to store results of sub-problems
    cache = {(n, m): 1}

    # Iterate over each pass
    for pass_num in range(m):
        # Iterate over each student
        for student in range(n):
            # Determine the number of passing ways for the student
            passing_ways = 0
            if student > 0:
                passing_ways += cache[(student - 1, pass_num)]
            if student < n - 1:
                passing_ways += cache[(student + 1, pass_num)]

            # Add the number of passing ways for the student to the cache
            cache[(student, pass_num + 1)] = passing_ways

    # Return the final number of passing ways for the starting student
    return cache[(0, m)]

