def count_sequences(n: int, last: int, memo: dict) -> int:
    if n < 1 or last < 1:
        return 0
    if n == last:
        return 1
    if last in memo:
        return memo[last]
    count = 0
    for i in range(1, int(last/2 + 1)):
        count += count_sequences(n, i, memo)
    memo[last] = count
    return count

