    max_unhappiness = max(map(sum, unhappy_days))
    return unhappy_days[max_unhappiness].index(max_unhappiness) + 1

def next_permutation(perm: list) -> bool:
    if perm == sorted(perm, reverse=True):
        return False
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            break
    smallest = i + 1
    for j in range(i + 2, len(perm)):
        if perm[j] > perm[i] and perm[j] < perm[smallest]:
            smallest = j
    perm[i], perm[smallest] = perm[smallest], perm[i]
    perm[i + 1:] = perm[len(perm) - 1:i:-1]
    return True

