def hanoi_double_iterative(n: int) -> int:
    if n == 0:
        return 0

    total_moves = 0
    for i in range(1, n+1):
        # Calculate the number of moves for each pair of discs
        moves_per_pair = pow(2, i)
        # Add the moves for each pair to the total number of moves
        total_moves += moves_per_pair

    return total_moves
